#include <stdlib.h>
#include <string.h>

#define MAXWORDS 100

int main() {
  char words[MAXWORDS][MAXWORDS] = malloc(sizeof(char) * MAXWORDS * MAXWORDS);

  printf("Enter 15 words, separating by spaces:\n");
  int numWords = 0;
  while(numWords < 15){
    scanf("%s", words[numWords]);
    numWords++;
  }

  // print out words:

  printf("\nWords: ");
  int numWordsUsed = 0;

  for(int i=0; i<numWords; i++){
    printf("%s ", words[i]);
    if(++numWordsUsed >= 15) printf("\n");
  }

  free(words);
  return 0;
}
